#include <vector>
#include <complex>
#include <algorithm>
#include <cmath>
#include <cstddef>
#include <omp.h>

void sortComplexByMagnitude(std::vector<std::complex<double>> &x) {
    const std::size_t n = x.size();
    if (n < 2) return;

    // Parallel stable mergesort:
    // 1) split into blocks, sort each block in parallel
    // 2) iteratively merge adjacent runs; merges are independent and parallelizable

    int max_threads = 1;
#pragma omp parallel
    {
#pragma omp single
        { max_threads = omp_get_num_threads(); }
    }
    if (max_threads < 1) max_threads = 1;

    // Choose block count (power-of-two-ish not required; we handle tails)
    const std::size_t blocks = static_cast<std::size_t>(max_threads);
    const std::size_t blockSize = (n + blocks - 1) / blocks;

    auto mag2 = [](const std::complex<double> &z) -> double {
        // squared magnitude avoids sqrt and preserves ordering
        const double re = z.real();
        const double im = z.imag();
        return re * re + im * im;
    };

    auto comp = [&](const std::complex<double> &a, const std::complex<double> &b) -> bool {
        return mag2(a) < mag2(b);
    };

    // Sort each block independently
#pragma omp parallel for schedule(static)
    for (std::ptrdiff_t bi = 0; bi < static_cast<std::ptrdiff_t>(blocks); ++bi) {
        const std::size_t begin = static_cast<std::size_t>(bi) * blockSize;
        if (begin >= n) continue;
        const std::size_t end = std::min(n, begin + blockSize);
        std::stable_sort(x.begin() + static_cast<std::ptrdiff_t>(begin),
                         x.begin() + static_cast<std::ptrdiff_t>(end),
                         comp);
    }

    // Temporary buffer for merges
    std::vector<std::complex<double>> tmp(n);

    // Merge runs of size runSize, doubling each pass.
    // Alternate between x -> tmp and tmp -> x to avoid extra copies.
    bool fromXtoTmp = true;
    for (std::size_t runSize = blockSize; runSize < n; runSize *= 2) {
        const std::size_t numPairs = (n + 2 * runSize - 1) / (2 * runSize);

        if (fromXtoTmp) {
#pragma omp parallel for schedule(static)
            for (std::ptrdiff_t p = 0; p < static_cast<std::ptrdiff_t>(numPairs); ++p) {
                const std::size_t left = static_cast<std::size_t>(p) * 2 * runSize;
                const std::size_t mid  = std::min(n, left + runSize);
                const std::size_t right = std::min(n, left + 2 * runSize);

                // If only one run exists, just copy it
                if (mid >= right) {
                    std::copy(x.begin() + static_cast<std::ptrdiff_t>(left),
                              x.begin() + static_cast<std::ptrdiff_t>(right),
                              tmp.begin() + static_cast<std::ptrdiff_t>(left));
                } else {
                    std::stable_merge(x.begin() + static_cast<std::ptrdiff_t>(left),
                                      x.begin() + static_cast<std::ptrdiff_t>(mid),
                                      x.begin() + static_cast<std::ptrdiff_t>(right),
                                      tmp.begin() + static_cast<std::ptrdiff_t>(left),
                                      comp);
                }
            }
        } else {
#pragma omp parallel for schedule(static)
            for (std::ptrdiff_t p = 0; p < static_cast<std::ptrdiff_t>(numPairs); ++p) {
                const std::size_t left = static_cast<std::size_t>(p) * 2 * runSize;
                const std::size_t mid  = std::min(n, left + runSize);
                const std::size_t right = std::min(n, left + 2 * runSize);

                if (mid >= right) {
                    std::copy(tmp.begin() + static_cast<std::ptrdiff_t>(left),
                              tmp.begin() + static_cast<std::ptrdiff_t>(right),
                              x.begin() + static_cast<std::ptrdiff_t>(left));
                } else {
                    std::stable_merge(tmp.begin() + static_cast<std::ptrdiff_t>(left),
                                      tmp.begin() + static_cast<std::ptrdiff_t>(mid),
                                      tmp.begin() + static_cast<std::ptrdiff_t>(right),
                                      x.begin() + static_cast<std::ptrdiff_t>(left),
                                      comp);
                }
            }
        }

        fromXtoTmp = !fromXtoTmp;
    }

    // If the final result is in tmp, copy back to x
    if (!fromXtoTmp) {
        x.swap(tmp);
    }
}
